const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsa = ee.Geometry.Point([139.5, -20.7]);
  const townsville = ee.Geometry.Point([146.8, -19.3]);
  const startDate = '2019-01-27';
  const endDate = '2019-02-11'; // Inclusive of Feb 10

  // 2. Data Acquisition - GPM IMERG (precipitation in mm/hr)
  const gpm = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filter(ee.Filter.date(startDate, endDate))
    .select('precipitation');

  const collectionSize = gpm.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log("No precipitation data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over time period
  // GPM data is in mm/hr, so multiply by 0.5 hours (30-min intervals) to get mm per image
  const totalPrecip = gpm.map(function(img) {
    return img.multiply(0.5); // Convert mm/hr to mm per 30-min
  }).sum();

  // 4. Calculate for Mount Isa
  const mountIsaStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mountIsa,
    scale: 10000,
    maxPixels: 1e9
  });

  const mountIsaCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mountIsa,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const mountIsaRainfall = mountIsaStats.get('precipitation').getInfo();

  // 5. Calculate for Townsville
  const townsvilleStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsville,
    scale: 10000,
    maxPixels: 1e9
  });

  const townsvilleCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: townsville,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const townsvilleRainfall = townsvilleStats.get('precipitation').getInfo();

  // 6. Validation
  if (mountIsaCount === 0 || townsvilleCount === 0) {
    console.log(`Mount Isa pixels: ${mountIsaCount}, Townsville pixels: ${townsvilleCount}`);
    console.log("<answer>C2</answer>");
    return;
  }

  if (mountIsaRainfall === null || townsvilleRainfall === null || 
      isNaN(mountIsaRainfall) || isNaN(townsvilleRainfall)) {
    console.log("Calculation failed - null or NaN result");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Mount Isa total rainfall: ${mountIsaRainfall.toFixed(2)} mm`);
  console.log(`Townsville total rainfall: ${townsvilleRainfall.toFixed(2)} mm`);
  console.log(`Threshold: 450 mm (45 cm)`);

  // 7. Final Answer - BOTH regions need >= 450mm
  if (mountIsaRainfall >= 450 && townsvilleRainfall >= 450) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
